% Lab 6: Random Number Generation
% Lab Goal: Simulate a theoretical measurement with noise generated by a random number generator.
% INPUT: No Input required from the user
% OUTPUT: Plots and output files showing the results of the random number generation and analysis.

% Setup Lab
clear; clc;

% Setup Variables
amp = 3; % Amplitude of the random signal 3mm
freq = 0.5; % Frequency of the random signal 0.5Hz
sampleSize = 500; % Number of samples to generate
fileID = fopen('output.txt', 'w'); % Open file for writing

% Summary of the results
topSummary = (["Name: James Prime",...
"Student ID: 215028657",...
"TA: Miodrag Tasic",...
'Lab 6: Random Number Generation',...
'Lab Goal: Simulate a theoretical measurement with noise generated by a random number generator.',...
'INPUT: No Input required from the user',...
'OUTPUT: Plots and output files showing the results of the random number generation and analysis.']);

summary = "The purpose of this lab is to simulate a theoretical measurement with noise generated by a random number generator.";
objectives = "The objectives include generating random noise, analyzing the data, and plotting the results.";
fprintf(fileID, '%s\n', topSummary);
fprintf(fileID, '\n%s\n', summary);
fprintf(fileID, '%s\n\n', objectives);

% generate time vector for random signal
timeInterval = linspace(0, 10, sampleSize); % Time vector from 0 to 10 seconds with sampleSize points

% Part 1: generate theoretical signal and add noise
theoretical = amp*sin(2*pi*freq*timeInterval); % Theoretical signal without noise
noise = 0.7*randn(1, sampleSize); % Generate random noise
measured = theoretical + noise; % Measured signal with noise

% Part 2: Calculate mean error, mean absolute error, largest absolute error, ...
% percentage with an absolute error of no greater than 1mm of the measured signal
% calculate standard deviation
trueError = measured - theoretical; % True error
meanError = mean(trueError); % Mean error
absoluteError = abs(trueError); % Absolute error
meanAbsoluteError = mean(absoluteError); % Mean absolute error
largestAbsoluteError = max(absoluteError); % Largest absolute error
percentageWithinBound = sum(absoluteError <= 1)/sampleSize * 100; % Percentage within 1mm bound
stdDevMeasurement = std(measured); % Calculate the standard deviation of the measurment

% Part 3: Write to external txt file, output.txt
%   1. Mean Error.
%   2. Mean Absolute Error.
%   3. Largest Absolute Error
%   4. Percentage of measurements with an absolute error no greater than 1mm
%   5. Standard deviation
fprintf(fileID, 'The Mean Error is: %.2f mm\n', meanError);
fprintf(fileID, 'The Mean Absolute Error is: %.2f mm\n', meanAbsoluteError);
fprintf(fileID, 'The Largest Absolute Error is: %.2f mm\n', largestAbsoluteError);
fprintf(fileID, 'Percentage of measurements with an absolute error no greater than 1mm: %.2f%%\n', percentageWithinBound);
fprintf(fileID, 'The standard deviation for the measurments: %.2f mm\n\n', stdDevMeasurement);


% Part 4: Write to external txt file, output.txt
%   1. Percentage of measured displacements above zero.
%   2. Percentage of measured displacements below zero.
%   3. Number of measurements with absoluteMeasured > 3 mm
%   4. Mean measured displacement when the theoretical displacement is positive
aboveZeroPercentage = sum(measured > 0)/sampleSize * 100; % Percentage above zero
belowZeroPercentage = sum(measured < 0)/sampleSize * 100; % Percentage below zero
numAboveAbsThree = sum(abs(measured) > 3); % Number of measurements with absolute value greater than 3 mm
meanPosTheoretical = mean(measured(theoretical > 0)); % Mean measured displacement when theoretical is positive

fprintf(fileID, 'Percentage of measured displacements above zero: %.2f%%\n', aboveZeroPercentage);
fprintf(fileID, 'Percentage of measured displacements below zero: %.2f%%\n', belowZeroPercentage);
fprintf(fileID, 'Number of measurements with absolute measurement > 3 mm: %d\n', numAboveAbsThree);
fprintf(fileID, 'Mean measured displacement when the theoretical displacement is positive: %.2f mm\n', meanPosTheoretical);

% Close File
fclose(fileID);

% Part 5: Plot Two Subplots
% First Subplot: Theoretical and Measured Displacements wrt Time
% Second Subplot: Measured (True) Error wrt Time
figure; % Create a new figure window

% First Subplot
subplot(2, 1, 1); % Create first subplot
hold on; 
plot(timeInterval, measured, 'b.'); %plot measured signal in blue
plot(timeInterval, theoretical, 'k-'); %plot theoretical signal in black
grid on; % Enable grid
xlabel('Time, t (s)'); % Label x-axis
ylabel('Displacement y(mm)'); % Label y-axis
title('Measured and Theoretical Displacements'); % Title for the subplot
legend('Measured displacement', 'Theoretical sinusoidal', 'Location', 'best'); % Add legend

% Second Subplot
subplot(2, 1, 2); % Create second subplot 
hold on;
plot(timeInterval, trueError, 'r.'); % Plot true error in red
plot(timeInterval, zeros(size(timeInterval)), 'k--'); %plot zero line in black
grid on; % Enable grid
xlabel('Time, t (s)'); % Label x-axis
ylabel('Measurement Error, e (mm)'); % Label y-axis
title('Measurement Error versus Time'); % Title for the subplot
legend('Measurement Error', 'Zero Error', 'Location', 'best'); % Add legend